  "text": "import numpy as np\nfrom sklearn.datasets import make_moons, make_blobs\nfrom sklearn.cluster import KMeans, DBSCAN, AgglomerativeClustering\nfrom sklearn.metrics import adjusted_rand_score\n\nX_moons, y_moons = make_moons(n_samples=500, noise=0.07, random_state=0)\nX_var, y_var = make_blobs(n_samples=[400, 100, 100], centers=[[0, 0], [4, 3], [5, -2]],\n                          cluster_std=[1.6, 0.4, 0.4], random_state=0)\n\nmodels = {\n    'k-means': lambda: KMeans(n_clusters=2, n_init=10, random_state=0),\n    'DBSCAN eps=0.2': lambda: DBSCAN(eps=0.2, min_samples=5),\n    'single linkage': lambda: AgglomerativeClustering(n_clusters=2, linkage='single'),\n    'ward linkage': lambda: AgglomerativeClustering(n_clusters=2, linkage='ward'),\n}\nprint('«луны», ARI с истинной разметкой:')\nfor name, make in models.items():\n    labels = make().fit_predict(X_moons)\n    extra = f'  шум: {(labels == -1).sum()}' if 'DBSCAN' in name else ''\n    print(f'  {name:16s} {adjusted_rand_score(y_moons, labels):.3f}{extra}')\n\nprint('кластеры разного размера и плотности (3 кластера):')\nfor name, m in [('k-means', KMeans(n_clusters=3, n_init=10, random_state=0)),\n                ('ward linkage', AgglomerativeClustering(n_clusters=3, linkage='ward')),\n                ('DBSCAN eps=0.5', DBSCAN(eps=0.5, min_samples=5))]:\n    labels = m.fit_predict(X_var)\n    sizes = np.bincount(labels[labels >= 0])\n    print(f'  {name:16s} ARI {adjusted_rand_score(y_var, labels):.3f}  размеры кластеров: {sizes.tolist()}'\n          + (f'  шум: {(labels == -1).sum()}' if (labels == -1).any() else ''))",
