  "text": "import numpy as np\nfrom sklearn.datasets import load_digits\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.cluster import KMeans, AgglomerativeClustering\nfrom sklearn.metrics import adjusted_rand_score, normalized_mutual_info_score, silhouette_score\n\nX, y = load_digits(return_X_y=True)          # 1797 картинок 8×8, 10 цифр\nlabels = KMeans(n_clusters=10, n_init=10, random_state=0).fit_predict(X)\n\nprint('ARI:', round(adjusted_rand_score(y, labels), 3), ' NMI:', round(normalized_mutual_info_score(y, labels), 3))\n# переименование кластеров не меняет метрики\nperm = np.random.default_rng(0).permutation(10)\nprint('после перестановки номеров:', round(adjusted_rand_score(y, perm[labels]), 3))\n# случайная разметка — около нуля\nrand = np.random.default_rng(0).integers(0, 10, len(y))\nprint('случайная разметка: ARI', round(adjusted_rand_score(y, rand), 3), ' NMI', round(normalized_mutual_info_score(y, rand), 3))\n\n# какой цифре соответствует каждый кластер\nfor c in range(10):\n    digits, counts = np.unique(y[labels == c], return_counts=True)\n    top = counts.argmax()\n    print(f'кластер {c}: {counts.sum():3d} объектов, чаще всего цифра {digits[top]} ({counts[top] / counts.sum():.0%})')",
